import subprocess, time

def get_prompt(args):
    subprocess.run(['tmux', 'new-session', '-d', '-s', 't1', '-x', '100', '-y', '30', f'./executable {args}'])
    time.sleep(0.2)
    res = subprocess.check_output(['tmux', 'capture-pane', '-t', 't1', '-p']).decode('utf-8')
    subprocess.run(['tmux', 'kill-session', '-t', 't1'], stderr=subprocess.DEVNULL)
    lines = [line.strip() for line in res.splitlines() if line.strip()]
    return ' '.join(lines)

for i in range(5):
    print(i, get_prompt('-w 5'))
""}

