{"command":"python3 -c "
import subprocess, time

def test_margin(w):
    subprocess.run(['tmux', 'new-session', '-d', '-s', 't1', '-x', str(w), '-y', '24', './executable -p \"hello\"'])
    time.sleep(0.2)
    res = subprocess.check_output(['tmux', 'capture-pane', '-t', 't1', '-p']).decode('utf-8')
    subprocess.run(['tmux', 'kill-session', '-t', 't1'], stderr=subprocess.DEVNULL)
    for i, line in enumerate(res.splitlines()):
        if line.strip():
            spaces = len(line) - len(line.lstrip())
            print(f'Width {w}: Line {i}, leading spaces={spaces}, line={repr(line)}')

for w in [40, 60, 80, 100, 120, 160]:
    test_margin(w)
""}

