import subprocess, time

def test_wrap_margin(w):
    long_p = \"the quick brown fox jumps over the lazy dog the quick brown fox jumps over the lazy dog the quick brown fox jumps over the lazy dog\"
    subprocess.run(['tmux', 'new-session', '-d', '-s', 't1', '-x', str(w), '-y', '24', f'./executable -p \"{long_p}\"'])
    time.sleep(0.2)
    res = subprocess.check_output(['tmux', 'capture-pane', '-t', 't1', '-p']).decode('utf-8')
    subprocess.run(['tmux', 'kill-session', '-t', 't1'], stderr=subprocess.DEVNULL)
    print(f'=== Width {w} ===')
    for i, line in enumerate(res.splitlines()):
        if line.strip():
            spaces = len(line) - len(line.lstrip())
            print(f'Line {i}, leading spaces={spaces}, len={len(line.strip())}')

for w in [40, 60, 80, 100, 120, 160]:
    test_wrap_margin(w)
""}

