pub fn generate_sentences(n: usize) -> String {
    let mut rng = rand::thread_rng();
    let mut s_list = Vec::with_capacity(n);

    for _ in 0..n {
        let pattern = [0, 1, 2, 3, 4].choose(&mut rng).copied().unwrap_or(0);
