pub fn generate_sentences(n: usize) -> String {
    let mut rng = rand::thread_rng();
    let mut s_list = Vec::with_capacity(n);

    for _ in 0..n {
        let pattern = [0, 1, 2, 3, 4].choose(&mut rng).copied().unwrap_or(0);
        let mut words = Vec::new();

        let use_the = [true, false].choose(&mut rng).copied().unwrap_or(true);
        if use_the {
            words.push("The".to_string());
        }

        match pattern {
            0 => {
                words.push(ADJECTIVES.choose(&mut rng).unwrap().to_string());
                words.push(COLORS_MATERIALS.choose(&mut rng).unwrap().to_string());
                words.push(NOUNS.choose(&mut rng).unwrap().to_string());
                words.push(ADVERBS.choose(&mut rng).unwrap().to_string());
                words.push(VERBS.choose(&mut rng).unwrap().to_string());
                if [true, false].choose(&mut rng).copied().unwrap_or(true) {
                    words.push("the".to_string());
                    words.push(ADJECTIVES.choose(&mut rng).unwrap().to_string());
                    words.push(NOUNS.choose(&mut rng).unwrap().to_string());
                }
            }
            1 => {
                words.push(ADJECTIVES.choose(&mut rng).unwrap().to_string());
                words.push(NOUNS.choose(&mut rng).unwrap().to_string());
                words.push(ADVERBS.choose(&mut rng).unwrap().to_string());
                words.push(ADVERBS.choose(&mut rng).unwrap().to_string());
                words.push(VERBS.choose(&mut rng).unwrap().to_string());
            }
            2 => {
                words.push(COLORS_MATERIALS.choose(&mut rng).unwrap().to_string());
                words.push(NOUNS.choose(&mut rng).unwrap().to_string());
                words.push(VERBS.choose(&mut rng).unwrap().to_string());
                words.push(ADVERBS.choose(&mut rng).unwrap().to_string());
                words.push(ADVERBS.choose(&mut rng).unwrap().to_string());
            }
            3 => {
                words.push(ADJECTIVES.choose(&mut rng).unwrap().to_string());
                words.push(NOUNS.choose(&mut rng).unwrap().to_string());
                words.push(VERBS.choose(&mut rng).unwrap().to_string());
                words.push(ADVERBS.choose(&mut rng).unwrap().to_string());
                words.push("the".to_string());
                words.push(COLORS_MATERIALS.choose(&mut rng).unwrap().to_string());
                words.push(NOUNS.choose(&mut rng).unwrap().to_string());
            }
            _ => {
                words.push(ADJECTIVES.choose(&mut rng).unwrap().to_string());
                words.push(COLORS_MATERIALS.choose(&mut rng).unwrap().to_string());
                words.push(NOUNS.choose(&mut rng).unwrap().to_string());
                words.push(VERBS.choose(&mut rng).unwrap().to_string());
            }
        }

        // Capitalize first word
        if let Some(first) = words.first_mut() {
            let mut chars = first.chars();
            if let Some(f) = chars.next() {
                *first = format!("{}{}", f.to_uppercase(), chars.as_str());
            }
        }

        let sentence = format!("{}.", words.join(" "));
        s_list.push(sentence);
    }

    s_list.join(" ")
}
EOF
