use ratatui::{
    layout::{Alignment, Constraint, Direction, Layout, Rect},
    style::{Color, Modifier, Style},
    symbols,
    text::{Line, Span},
    widgets::{Axis, Chart, Dataset, GraphType, Paragraph, Wrap},
    Frame,
};

use crate::app::{App, Screen};

pub fn draw(f: &mut Frame, app: &App) {
    match app.screen {
        Screen::Typing => draw_typing(f, app),
        Screen::Results => draw_results(f, app),
    }
}

fn draw_typing(f: &mut Frame, app: &App) {
    let mut spans = Vec::with_capacity(app.prompt_chars.len());

    for (i, &ch) in app.prompt_chars.iter().enumerate() {
        if i < app.cursor {
            if app.typed_inputs[i] == Some(ch) {
                spans.push(Span::styled(
                    ch.to_string(),
                    Style::default().fg(Color::Green).add_modifier(Modifier::BOLD),
                ));
            } else {
                spans.push(Span::styled(
                    ch.to_string(),
                    Style::default().fg(Color::Red).add_modifier(Modifier::BOLD),
                ));
            }
        } else if i == app.cursor {
            spans.push(Span::styled(
                ch.to_string(),
                Style::default().add_modifier(Modifier::DIM | Modifier::UNDERLINE),
            ));
        } else {
            spans.push(Span::styled(
                ch.to_string(),
                Style::default().add_modifier(Modifier::DIM | Modifier::BOLD),
            ));
        }
    }

    let line = Line::from(spans);

    let area = f.area();
    let area_width = area.width as usize;
    let text_len = app.prompt_chars.len();

    // Approximate wrapped lines count
    let usable_width = if area_width > 10 { area_width - 10 } else { area_width };
    let lines_count = if usable_width > 0 {
        (text_len + usable_width - 1) / usable_width
    } else {
        1
    };

    let top_padding = if (area.height as usize) > lines_count {
        (area.height as usize - lines_count) / 2
    } else {
        0
    };

    let chunks = Layout::default()
        .direction(Direction::Vertical)
        .constraints([
            Constraint::Length(top_padding as u16),
            Constraint::Min(1),
        ])
        .split(area);

    let paragraph = Paragraph::new(line)
        .alignment(Alignment::Center)
        .wrap(Wrap { trim: true });

    f.render_widget(paragraph, chunks[1]);
}

fn draw_results(f: &mut Frame, app: &App) {
    let chunks = Layout::default()
        .direction(Direction::Vertical)
        .constraints([
            Constraint::Length(2),
            Constraint::Min(5),
            Constraint::Length(1),
            Constraint::Length(1),
            Constraint::Length(1),
            Constraint::Length(2),
        ])
        .split(f.area());

    let chart_chunks = Layout::default()
        .direction(Direction::Horizontal)
        .constraints([
            Constraint::Percentage(5),
            Constraint::Percentage(90),
            Constraint::Percentage(5),
        ])
        .split(chunks[1]);

    let data: Vec<(f64, f64)> = app
        .wpm_samples
        .iter()
        .map(|&(t, w)| (t, if w.is_infinite() || w.is_nan() { 0.0 } else { w }))
        .collect();

    let dataset = Dataset::default()
        .marker(symbols::Marker::Braille)
        .graph_type(GraphType::Line)
        .data(&data);

    let x_max = if app.elapsed_time.as_secs_f64() == 0.0 {
        1.0
    } else {
        app.elapsed_time.as_secs_f64()
    };

    let y_max_label = if app.final_wpm_str == "inf" {
        "inf".to_string()
    } else {
        format!("{:.0}", app.max_wpm)
    };

    let y_max_val = if app.final_wpm_str == "inf" {
        240.0
    } else {
        app.max_wpm
    };

    let chart = Chart::new(vec![dataset])
        .x_axis(
            Axis::default()
                .title("seconds")
                .bounds([1.0, x_max])
                .labels(vec!["1".into(), format!("{:.2}", x_max).into()]),
        )
        .y_axis(
            Axis::default()
                .title("wpm")
                .bounds([0.0, y_max_val])
                .labels(vec!["0".into(), y_max_label.into()]),
        );

    f.render_widget(chart, chart_chunks[1]);

    let summary_text = format!(
        "{} wpm   {}% acc   {:.2} sd",
        app.final_wpm_str, app.final_accuracy, app.final_std_dev
    );
    let summary_p = Paragraph::new(summary_text)
        .alignment(Alignment::Center)
        .style(Style::default().add_modifier(Modifier::BOLD));
    f.render_widget(summary_p, chunks[2]);

    let nav_text = "(r)etry / (n)ew / (esc)ape";
    let nav_p = Paragraph::new(nav_text)
        .alignment(Alignment::Center)
        .style(Style::default().add_modifier(Modifier::ITALIC));
    f.render_widget(nav_p, chunks[4]);
}
EOF
