        std::process::exit(2);
    }

    let config = Config {
        number_of_words: *matches.get_one::<usize>("number-of-words").unwrap_or(&15),
        number_of_secs: matches.get_one::<usize>("number-of-secs").copied(),
        full_sentences: matches.get_one::<usize>("full-sentences").copied(),
        supported_language: matches
