                if key.kind == KeyEventKind::Press {
                    match app.screen {
                        Screen::Typing => match key.code {
                            KeyCode::Esc => break,
                            KeyCode::Char('c') if key.modifiers.contains(KeyModifiers::CONTROL) => {
                                break
                            }
                            KeyCode::Left => app.restart_same_prompt(),
                            KeyCode::Right => app.generate_new_prompt(),
                            KeyCode::Backspace => app.handle_backspace(),
                            KeyCode::Char(c) => app.handle_key_char(c),
                            _ => {}
                        },
                        Screen::Results => match key.code {
                            KeyCode::Esc => break,
                            KeyCode::Char('c') if key.modifiers.contains(KeyModifiers::CONTROL) => {
                                break
                            }
                            KeyCode::Char('r') | KeyCode::Left => app.restart_same_prompt(),
                            KeyCode::Char('n') | KeyCode::Right => app.generate_new_prompt(),
                            _ => {}
                        },
                    }
                }
            }
        }

        app.update_tick();
    }

    disable_raw_mode()?;
    execute!(terminal.backend_mut(), LeaveAlternateScreen)?;
    terminal.show_cursor()?;

    Ok(())
}
