{"command":"cat <<'EOF' > src/app.rs
use std::fs::{self, OpenOptions};
use std::io::Write;
use std::path::PathBuf;
use std::time::{Duration, Instant};

use chrono::Local;
use rand::seq::SliceRandom;

use crate::dict::get_language_words;
use crate::sentence::generate_sentences;

#[derive(Debug, PartialEq, Eq)]
pub enum Screen {
    Typing,
    Results,
}

pub struct Config {
    pub number_of_words: usize,
    pub number_of_secs: Option<usize>,
    pub full_sentences: Option<usize>,
    pub supported_language: String,
    pub custom_prompt: Option<String>,
}

pub struct App {
    pub config: Config,
    pub screen: Screen,
    pub prompt: String,
    pub prompt_chars: Vec<char>,
    pub typed_inputs: Vec<Option<char>>,
    pub cursor: usize,

    pub start_time: Option<Instant>,
    pub elapsed_time: Duration,
    pub wpm_samples: Vec<(f64, f64)>, // (time_sec, wpm)
    pub last_sample_sec: u64,

    pub final_wpm_str: String,
    pub final_accuracy: usize,
    pub final_std_dev: f64,
    pub max_wpm: f64,
}

impl App {
    pub fn new(config: Config) -> Self {
        let mut app = Self {
            config,
            screen: Screen::Typing,
            prompt: String::new(),
            prompt_chars: Vec::new(),
            typed_inputs: Vec::new(),
            cursor: 0,
            start_time: None,
            elapsed_time: Duration::ZERO,
            wpm_samples: Vec::new(),
            last_sample_sec: 0,
            final_wpm_str: String::new(),
            final_accuracy: 0,
            final_std_dev: 0.0,
            max_wpm: 0.0,
        };

        app.generate_new_prompt();
        if app.prompt.is_empty()
            || app.config.number_of_words == 0
            || app.config.number_of_secs == Some(0)
            || app.config.full_sentences == Some(0)
        {
            app.finish_test();
        }
        app
    }

    pub fn generate_new_prompt(&mut self) {
        if let Some(ref p) = self.config.custom_prompt {
            self.prompt = p.clone();
        } else if let Some(f) = self.config.full_sentences {
            if f == 0 {
                self.prompt = String::new();
            } else {
                self.prompt = generate_sentences(f);
            }
        } else {
            if self.config.number_of_words == 0 {
                self.prompt = String::new();
            } else {
                let words = get_language_words(&self.config.supported_language);
                let mut rng = rand::thread_rng();
                let selected = words.choose_multiple(&mut rng, self.config.number_of_words);
                let selected_vec: Vec<&str> = selected.copied().collect();
                self.prompt = selected_vec.join(" ");
            }
        }

        self.reset_test_state();
    }

    pub fn reset_test_state(&mut self) {
        self.prompt_chars = self.prompt.chars().collect();
        self.typed_inputs = vec![None; self.prompt_chars.len()];
        self.cursor = 0;
        self.start_time = None;
        self.elapsed_time = Duration::ZERO;
        self.wpm_samples.clear();
        self.last_sample_sec = 0;
        self.screen = Screen::Typing;
    }

    pub fn restart_same_prompt(&mut self) {
        self.typed_inputs = vec![None; self.prompt_chars.len()];
        self.cursor = 0;
        self.start_time = None;
        self.elapsed_time = Duration::ZERO;
        self.wpm_samples.clear();
        self.last_sample_sec = 0;
        self.screen = Screen::Typing;
    }

    pub fn handle_key_char(&mut self, c: char) {
        if self.screen != Screen::Typing {
            return;
        }

        if self.start_time.is_none() {
            self.start_time = Some(Instant::now());
        }

        if self.cursor < self.prompt_chars.len() {
            self.typed_inputs[self.cursor] = Some(c);
            self.cursor += 1;

            if self.cursor == self.prompt_chars.len() {
                self.finish_test();
            }
        }
    }

    pub fn handle_backspace(&mut self) {
        if self.screen != Screen::Typing {
            return;
        }

        if self.cursor > 0 {
            self.cursor -= 1;
            self.typed_inputs[self.cursor] = None;
        }
    }

    pub fn update_tick(&mut self) {
        if self.screen != Screen::Typing {
            return;
        }

        if let Some(start) = self.start_time {
            let elapsed = start.elapsed();
            self.elapsed_time = elapsed;

            let elapsed_secs = elapsed.as_secs();
            if elapsed_secs > self.last_sample_sec {
                self.last_sample_sec = elapsed_secs;
                let cur_wpm = self.calc_current_wpm(elapsed);
                self.wpm_samples.push((elapsed_secs as f64, cur_wpm));
            }

            if let Some(limit_secs) = self.config.number_of_secs {
                if elapsed >= Duration::from_secs(limit_secs as u64) {
                    self.finish_test();
                }
            }
        }
    }

    fn calc_correct_count(&self) -> usize {
        let mut count = 0;
        for i in 0..self.cursor {
            if i < self.prompt_chars.len() && self.typed_inputs[i] == Some(self.prompt_chars[i]) {
                count += 1;
            }
        }
        count
    }

    fn calc_current_wpm(&self, elapsed: Duration) -> f64 {
        let correct = self.calc_correct_count();
        let secs = elapsed.as_secs_f64().ceil().max(1.0);
        (correct as f64 * 12.0) / secs
    }

    pub fn finish_test(&mut self) {
        if let Some(start) = self.start_time {
            self.elapsed_time = start.elapsed();
        } else {
            self.elapsed_time = Duration::ZERO;
        }

        let correct = self.calc_correct_count();
        let total = self.prompt_chars.len();
        let real_secs = self.elapsed_time.as_secs_f64();
        let rounded_secs = real_secs.ceil();

        // WPM string
        if real_secs == 0.0 {
            if correct == 0 {
                self.final_wpm_str = "0".to_string();
            } else {
                self.final_wpm_str = "inf".to_string();
            }
        } else {
            let wpm_denom = rounded_secs.max(1.0);
            let wpm_val = ((correct as f64 * 12.0) / wpm_denom).round();
            self.final_wpm_str = format!("{:.0}", wpm_val);
        }

        // Accuracy
        if total == 0 {
            self.final_accuracy = 0;
        } else {
            self.final_accuracy = ((correct as f64 / total as f64) * 100.0).round() as usize;
        }

        let final_wpm_val = if real_secs == 0.0 {
            if correct == 0 { 0.0 } else { f64::INFINITY }
        } else {
            (correct as f64 * 12.0) / rounded_secs.max(1.0)
        };

        if self.wpm_samples.is_empty() {
            self.wpm_samples.push((rounded_secs.max(1.0), final_wpm_val));
        } else if self.wpm_samples.last().map(|p| p.0).unwrap_or(0.0) < rounded_secs {
            self.wpm_samples.push((rounded_secs.max(1.0), final_wpm_val));
        }

        // Max WPM for chart bounds
        self.max_wpm = self
            .wpm_samples
            .iter()
            .map(|&(_, w)| if w.is_infinite() { 0.0 } else { w })
            .fold(0.0, f64::max);

        // Std dev
        let finite_wpms: Vec<f64> = self
            .wpm_samples
            .iter()
            .map(|&(_, w)| w)
            .filter(|w| !w.is_infinite() && !w.is_nan())
            .collect();

        if finite_wpms.len() <= 1 {
            self.final_std_dev = 0.0;
        } else {
            let mean = finite_wpms.iter().sum::<f64>() / finite_wpms.len() as f64;
            let var =
                finite_wpms.iter().map(|w| (w - mean).powi(2)).sum::<f64>() / finite_wpms.len() as f64;
            self.final_std_dev = var.sqrt();
        }

        self.log_to_csv();
        self.screen = Screen::Results;
    }

    fn log_to_csv(&self) {
        let config_dir = dirs::config_dir()
            .unwrap_or_else(|| PathBuf::from("~/.config"))
            .join("thokr");

        if fs::create_dir_all(&config_dir).is_err() {
            return;
        }

        let log_file = config_dir.join("log.csv");
        let file_exists = log_file.exists();

        if let Ok(mut file) = OpenOptions::new().create(true).append(true).open(&log_file) {
            if !file_exists {
                let _ = writeln!(file, "date,num_words,num_secs,elapsed_secs,wpm,accuracy,std_dev");
            }

            let date_str = Local::now().format("%a %b %e %H:%M:%S %Y").to_string();

            let num_words_val = if self.config.full_sentences.is_some() {
                self.prompt.split_whitespace().count()
            } else {
                self.config.number_of_words
            };

            let num_secs_str = match self.config.number_of_secs {
                Some(s) => format!("{:.2}", s as f64),
                None => String::new(),
            };

            let elapsed_str = format!("{:.2}", self.elapsed_time.as_secs_f64());
            let std_dev_str = format!("{:.2}", self.final_std_dev);

            let _ = writeln!(
                file,
                "{},{},{},{},{},{},{}",
                date_str,
                num_words_val,
                num_secs_str,
                elapsed_str,
                self.final_wpm_str,
                self.final_accuracy,
                std_dev_str
            );
        }
    }
}
EOF
"}

